package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.port.PaymentOrderRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/** JDBC adapter of the PaymentOrderRepository port (table payment_order). */
@Repository
public class JdbcPaymentOrderRepository implements PaymentOrderRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcPaymentOrderRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<PaymentOrder> findByNumberAndCompany(Integer orderNumber, Integer companyId) {
        List<PaymentOrder> orders = jdbcTemplate.query(
                "SELECT order_number, company_id, status, payment_date, commission "
                        + "FROM payment_order WHERE order_number = ? AND company_id = ?",
                (rs, rowNum) -> {
                    Timestamp paymentDate = rs.getTimestamp("payment_date");
                    LocalDateTime date = paymentDate == null ? null : paymentDate.toLocalDateTime();
                    BigDecimal commission = rs.getBigDecimal("commission");
                    return new PaymentOrder(
                            rs.getInt("order_number"),
                            rs.getInt("company_id"),
                            rs.getString("status"),
                            date,
                            commission);
                },
                orderNumber, companyId);
        return orders.stream().findFirst();
    }

    @Override
    public int markPaid(Integer orderNumber, Integer companyId, LocalDateTime paymentDate, BigDecimal commission) {
        Timestamp timestamp = paymentDate == null ? null : Timestamp.valueOf(paymentDate);
        return jdbcTemplate.update(
                "UPDATE payment_order SET status = 'A', payment_date = ?, commission = ? "
                        + "WHERE order_number = ? AND company_id = ?",
                timestamp, commission, orderNumber, companyId);
    }
}
